import re
import unicodedata

import regex
from text_to_num import alpha2digit


# Language codes num2words ships a converter for. Hardcoded (rather than
# introspected from the installed package) so capability declarations don't
# change depending on whether the optional [tts] extra happens to be present.
NUM2WORDS_SUPPORTED_LANGS = frozenset({
    "am", "ar", "az", "be", "bn", "ca", "ce", "cs", "cy", "da", "de", "en",
    "eo", "es", "fa", "fi", "fr", "he", "hu", "id", "is", "it", "ja", "kn",
    "ko", "kz", "lt", "lv", "nl", "no", "pl", "pt", "ro", "ru", "sk", "sl",
    "sr", "sv", "te", "tet", "tg", "th", "tr", "uk", "vi",
})


def _num2words_module():
    try:
        import num2words as nw
    except ImportError:
        raise ImportError(
            "tts_mode requires the 'num2words' package: "
            "pip install 'whisper_normalizer[tts]'"
        ) from None
    return nw


def _validate_tts_lang(lang: str) -> None:
    """Raise if ``lang`` can't be used with tts_mode; imports num2words as a side effect."""
    _num2words_module()
    if lang not in NUM2WORDS_SUPPORTED_LANGS:
        raise ValueError(
            f"tts_mode is not supported for language {lang!r}: num2words has no converter for it"
        )


def _digits_to_words(text: str, lang: str) -> str:
    """Convert digit sequences (including decimals) to words using num2words."""
    nw = _num2words_module()

    def replace_num(m: re.Match) -> str:
        raw = m.group(0)
        try:
            value = float(raw) if "." in raw else int(raw)
            return nw.num2words(value, lang=lang)
        except Exception:
            return raw

    # Match a whole numeric token, including an optional decimal part, so
    # "1234.56" converts as one number instead of "1234" and "56" separately.
    return re.sub(r"\b\d+(?:\.\d+)?\b", replace_num, text)


class _LatinTextNormalizer:
    """Shared conservative normalization for space-separated Latin-script languages."""

    language: str
    number_threshold = 0

    def __init__(self, tts_mode: bool = False):
        if tts_mode:
            _validate_tts_lang(self.language)
        self.tts_mode = tts_mode

    def _normalize_numeric_separators(self, text: str) -> str:
        return text

    def _preprocess(self, text: str) -> str:
        return text

    def __call__(self, text: str) -> str:
        # NFC retains meaningful accents while making canonically equivalent text comparable.
        text = unicodedata.normalize("NFC", text).lower()
        text = re.sub(r"[<\[][^>\]]*[>\]]", "", text)
        text = re.sub(r"\(([^)]+?)\)", "", text)
        text = text.translate(str.maketrans({"\u2019": "'", "`": "'", "\u2010": "-", "\u2013": "-", "\u2014": "-"}))
        text = text.replace("\u200b", "").replace("\ufeff", "")
        if self.tts_mode:
            # Merge thousands separators and normalize the decimal mark first, so a
            # grouped/decimal number converts as one value instead of several.
            text = _digits_to_words(self._normalize_numeric_separators(text), self.language)
        else:
            text = alpha2digit(self._preprocess(text), self.language, threshold=self.number_threshold)
            text = self._normalize_numeric_separators(text)
        # Punctuation is a word boundary for Whisper-style comparison; accents remain intact.
        text = regex.sub(r"(?<!\d)[\p{P}\p{S}]+|[\p{P}\p{S}]+(?!\d)", " ", text)
        return re.sub(r"\s+", " ", text).strip()


class FrenchTextNormalizer(_LatinTextNormalizer):
    """Normalize French text without removing accents or ligatures."""

    language = "fr"

    def _normalize_numeric_separators(self, text: str) -> str:
        # French commonly groups thousands with a regular, no-break, or narrow no-break space.
        text = re.sub(r"(?<=\d)[ \u00a0\u202f](?=\d{3}(?:\D|$))", "", text)
        return re.sub(r"(?<=\d),(?=\d)", ".", text)


class SpanishTextNormalizer(_LatinTextNormalizer):
    """Normalize Spanish text without removing accents, dieresis, or enye."""

    language = "es"
    # Avoid treating the common articles un and una as numeric expressions.
    number_threshold = 2

    def _preprocess(self, text: str) -> str:
        return re.sub("\\bveinti\\u00fan\\b", "veintiuno", text)

    def _normalize_numeric_separators(self, text: str) -> str:
        # In Spanish, dots group thousands and commas separate decimal fractions.
        text = re.sub(r"(?<=\d)\.(?=\d{3}(?:\D|$))", "", text)
        return re.sub(r"(?<=\d),(?=\d)", ".", text)


