class _NonLatinTextNormalizer:
    """Shared punctuation and whitespace cleanup for non-Latin scripts."""

    language: str = ""

    def __init__(self, tts_mode: bool = False):
        if tts_mode:
            _validate_tts_lang(self.language)
        self.tts_mode = tts_mode

    def _prepare(self, text: str) -> str:
        return text

    def __call__(self, text: str) -> str:
        text = unicodedata.normalize("NFKC", text).lower()
        text = re.sub(r"[<\[][^>\]]*[>\]]", "", text)
        text = re.sub(r"\(([^)]+?)\)", "", text)
        text = text.replace("\u200b", "").replace("\ufeff", "")
        text = self._prepare(text)
        if self.tts_mode and self.language:
            text = _digits_to_words(text, self.language)
        text = regex.sub(r"(?<!\d)[\p{P}\p{S}]+|[\p{P}\p{S}]+(?!\d)", " ", text)
        return re.sub(r"\s+", " ", text).strip()


class ArabicTextNormalizer(_NonLatinTextNormalizer):
    """Normalize Arabic orthographic variants, diacritics, digits, and punctuation."""

    language = "ar"
    _digits = str.maketrans("٠١٢٣٤٥٦٧٨٩", "0123456789")

    def _prepare(self, text: str) -> str:
        text = text.translate(self._digits)
        text = re.sub(r"[\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06ed]", "", text)
        text = text.replace("ـ", "")
        text = text.translate(str.maketrans({"أ": "ا", "إ": "ا", "آ": "ا", "ٱ": "ا", "ؤ": "و", "ئ": "ي", "ى": "ي"}))
        text = re.sub(r"(?<=\d)٬(?=\d{3}(?:\D|$))", "", text)
        return re.sub(r"(?<=\d)[،٫](?=\d)", ".", text)


class ChineseTextNormalizer(_NonLatinTextNormalizer):
    """Normalize Chinese punctuation, whitespace, and common written numerals."""

    language = "zh"
    _numerals = {"零": 0, "〇": 0, "一": 1, "二": 2, "两": 2, "三": 3, "四": 4, "五": 5, "六": 6, "七": 7, "八": 8, "九": 9}
    _units = {"十": 10, "百": 100, "千": 1000, "万": 10000, "亿": 100000000}

    @classmethod
    def _number(cls, match: re.Match) -> str:
        value = match.group()
        if not any(char in cls._units for char in value):
            return "".join(str(cls._numerals[char]) for char in value)
        total = section = digit = 0
        last_large_unit = 1
        for char in value:
            if char in cls._numerals:
                digit = cls._numerals[char]
            else:
                unit = cls._units[char]
                if unit >= 10000:
                    section += digit
                    if not section and not total:
                        section = 1
                    if unit > last_large_unit:
                        total = (total + section) * unit
                    else:
                        total += section * unit
                    section = digit = 0
                    last_large_unit = unit
                else:
                    section += (digit or 1) * unit
                    digit = 0
        return str(total + section + digit)

    def __call__(self, text: str) -> str:
        text = super().__call__(text)
        if not self.tts_mode:
            # In TTS mode, Chinese numerals are already spoken form; skip digit conversion.
            text = re.sub(r"[零〇一二两三四五六七八九十百千万亿]+", self._number, text)
        return re.sub(r"\s+", "", text)


class RussianTextNormalizer(_NonLatinTextNormalizer):
    """Normalize Russian case, the optional letter ``ё``, and numeric separators."""

    language = "ru"

    def _prepare(self, text: str) -> str:
        text = text.replace("ё", "е")
        text = re.sub(r"(?<=\d)[ \u00a0\u202f](?=\d{3}(?:\D|$))", "", text)
        return re.sub(r"(?<=\d),(?=\d)", ".", text)

